#include <variant>

template<class... Ts>
struct overloaded : Ts... { using Ts::operator()...; };
template<class... Ts> overloaded(Ts...) -> overloaded<Ts...>;

using Shape = std::variant<Circle, Square>;

double area(const Shape& s) {
    return std::visit(overloaded{
        [](const Circle& c) { return 3.141592653589793 * c.r * c.r; },
        [](const Square& q) { return q.side * q.side; },
    }, s);                       // one lambda per alternative; no default case
}

struct Shape {
    enum Tag { Circle, Square } tag;
    union { double radius; double side; };
    static Shape circle(double r) { Shape s; s.tag = Circle; s.radius = r; return s; }
};

static double area(const Shape& s) {
    switch (s.tag) {
    case Shape::Circle: return 3.141592653589793 * s.radius * s.radius;
    case Shape::Square: return s.side * s.side;
    }
    abort();
}
